s"],"externalScripts":[],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\n\n\nlet lucene = \"\";\nconst rawQuery = context.grafana.replaceVariables(\"$search_message\").trim();\n\nif (rawQuery === \"\") {\n  lucene = \"msg:**\";\n} else {\n  const query = rawQuery.split(/\\s+/);\n  for (let word of query) {\n    if (\n      word === \"AND\" ||\n      word === \"OR\" ||\n      word === \"NOT\" ||\n      word === \"(\" ||\n      word === \")\"\n    ) {\n      lucene += word + \" \";\n    } else {\n      lucene += `msg:*${word}* `;\n    }\n  }\n  lucene = lucene.trim();\n}\n\ncontext.grafana.locationService.partial({ \"var-lucene_query\": lucene }, true);\n\ndocument.addEventListener(''keydown'', (e) =\u003e {\n  if (e.key == \"Enter\") {\n    context.grafana.refresh();\n  }\n})\n\n","renderMode":"allRows","styles":".dataTable {\n  width: 100%;\n}\n\n.ts {\n  min-width: 11vw;\n}\n\n.ss {\n  min-width: 5vw;\n}\n\n.msg {\n  min-width: 80vw;\n}\n\nth {\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"hide":false,"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"subsystem:${subsystem} AND (${lucene_query:text})","refId":"Logs","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{"_id":true,"_index":true,"_type":true,"courier":false,"data_stream.dataset":true,"data_stream.namespace":true,"data_stream.type":true,"event.original":true,"highlight":true,"location":true,"log.file.path":true,"sort":false},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp","event.original":"original"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":true,"field":"sort"}]}}],"transparent":true,"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"allowCustomValue":true,"current":{},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystem","multi":true,"name":"subsystem","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"msg:**","value":"msg:**"},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"msg:**","value":"msg:**"}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"description":"Remember to escape with a \"\\\" any of the following characters:\n+ - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\nThis searching supports AND, OR and NOT operators\nI.E.: NOT word1 - word1 AND word2 - ( word1 AND word2 ) OR word3","label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-15m","to":"now"},"timepicker":{},"timezone":"","title":"Logs","uid":"e5760f92-16d7-4175-8251-4b65f2413639","version":3}',1,'2