INSERT INTO dashboard VALUES(36,2,'telemetry','Telemetry','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":36,"links":[],"panels":[{"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS \u003e Weather Data \u003e Temperature","value":"GWS \u003e Weather Data \u003e Temperature"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS \u003e Weather Data \u003e Temperature","value":"GWS \u003e Weather Data \u003e Temperature"}],"query":"GWS \u003e Weather Data \u003e Temperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpTemp50m"],"value":["ws:cpTemp50m"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":2}',1,'2025-12-01 16:00:00','2025-12-09 15:47:51',1,1,0,'',33,0,0,'642d6862-e9a1-461d-9a06-85209807bc47',0,NULL,'v0alpha1','ef5sncf9sa6m8b');
INSERT INTO dashboard VALUES(37,35,'telemetry-2b-logs','Telemetry + Logs','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n  gap:1%;\n  padding: 0.5%;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Speed","value":"GWS\u003eWeather Data\u003eWind Speed"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Speed","value":"GWS\u003eWeather Data\u003eWind Speed"}],"query":"GHOST\u003eSlit Unit\u003eFilter Wheel\u003ePosition","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindSpeed"],"value":["ws:cpWindSpeed"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsyste