INSERT INTO dashboard_version VALUES(319,34,12,0,13,'2025-12-01 15:53:08',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":34,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":6,"x":0,"y":0},"id":4,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome:text}\");\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (!isHome) {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome) {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/642d6862-e9a1-461d-9a06-85209807bc47/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${keyDiv.dataset.path}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":14,"x":6,"y":0},"id":6,"options":{"afterRender":"","content":"\u003cdiv class=\"container\"\u003e\n  \u003cdiv class=\"header\"\u003e\n    \u003ch1\u003eWhat is TED?\u003c/h1\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"content\"\u003e\n    \u003cp\u003e\n      Telescope Engineering Data (TED) is a system for ingesting, storing, and viewing logs from numerous subsystems and\n      combining them with the telemetry data, all from the Gemini telescope. It provides a web interface based on\n      Grafana\n      software to visualize all data. Grafana is an open-source software that offers to create dashboards with\n      information\n      coming from multiple sources.\n    \u003c/p\u003e\n    \u003cp\u003e\n      In our case, we use 2 sources of data for TED Visualization:\n      - Logs: Logs are loaded from ASCII files and stored in Elasticsearch.\n      - Telemetry: Data is archived by the Archiver Appliance and retrieved using a helper python service\n    \u003c/p\u003e\n    \u003cp\u003e\n      We are committed to enhancing your user experience and providing a valuable tool for your work. Thank you for\n      being\n      part\n      of this journey. If you have any doubts or need further assistance, feel free to contact us in Slack or via email:\n      oscar.fuentes@noirlab.edu\n    \u003c/p\u003e\n    \u003c!-- Logos side by side with HTML and inline CSS --\u003e\n    \u003cdiv style=\"display: flex; justify-content: center; padding-top: 0%;\"\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo073.png\" alt=\"NOIRLab Logo\" style=\"max-width: 100%; width: 600px; margin: 10px;\" /\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo018.png\" alt=\"Gemini Observatory Logo\" style=\"max-width: 100%; width: 300px; margin: 10px;\" /\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"footer\"\u003e\u003cstrong\u003eVersion: 3.0.0\u003c/strong\u003e\u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles","default"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"\u0026{\n  position: relative;\n  display: flex;\n\n}\n.container {\n  padding: 20px;\n  position: fixed;\n  display: grid;\n  min-height:98%;\n  min-width: 99%;\n  grid-template-rows: auto 1fr auto;\n}\n\n.header{\n}\n\n.content{\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.footer{\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":4,"x":20,"y":0},"id":5,"options":{"afterRender":"","content":"\u003cdiv class=\"buttons-container\"\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eGeneral Dashboards\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/eikCiqgvg?orgId=1\" class=\"button-link\"\u003e\n      Telemetry\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/b8j_m3gDR?orgId=1\" class=\"button-link\"\u003e\n      Logs Only\n    \u003c/a\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eDaily Reports\u003c/h2\u003e\n    \u003chr\u003e\n    \u003cdiv class=\"horizontal-section\"\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Environment\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Seeing Monitor\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Telescope\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        OI\n      \u003c/a\u003e\n    \u003c/div\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Plan of the week\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Weekly Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Fault Reports\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Nightlog\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eCompilations\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Calibrations\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      IQ\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Temporary\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Versions\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eReal Time\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Time Probe\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Health\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eExternal Links\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Queue Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Phone Numbers\n    \u003c/a\u003e\n    \u003ca href=\"https://www.gemini.edu/\" class=\"button-link\"\u003e\n      Gemini Home\n    \u003c/a\u003e\n    \u003ca href=\"https://opswiki.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      OPS Wiki\n    \u003c/a\u003e\n    \u003ca href=\"http://swg.wikis-internal.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      SWG Wiki\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"  \u0026{\n    // background-color:${theme.colors.background.canvas};\n  }\n  .buttons-container {\n    display: flex;\n    justify-content: left;\n    align-items: center;\n    flex-direction: column;\n  }\n  \n  .button-section{\n    width: 100%;\n    // background-color:${theme.colors.background.canvas};\n    padding:20px;\n  }\n  .button-disabled{\n    pointer-events: none;\n    cursor: not-allowed;\n    color: gray !important;\n  }\n\n  .horizontal-section{\n    display: flex;\n    gap: 10px;\n  }\n\n  .button-link {\n    display: flex;\n    font-size: 1vh;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    width: 100%;\n    padding: 1%;\n    margin-bottom: 1%;\n    background-color: ${theme.colors.background.secondary};\n    color: ${theme.colors.text.primary};\n    text-decoration: none;\n    border: none;\n    border-radius: 5px;\n    cursor: pointer;\n  }\n  .button-link:hover{\n    background-color: ${theme.colors.background.canvas};\n    color: ${theme.colors.text.link};\n  }","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"}],"preload":false,"schemaVersion":41,"tags":[],"templating":{"list":[{"allowCustomValue":false,"current":{"text":"subsystems","value":"subsystems"},"description":"","hide":2,"label":"Category","name":"pvTreeCategory","options":[{"selected":false,"text":"Instruments","value":"instruments"},{"selected":true,"text":"Subsystems","value":"subsystems"}],"query":"Instruments : instruments, Subsystems : subsystems","type":"custom"},{"current":{"text":"true","value":"true"},"description":"","hide":2,"name":"isHome","options":[{"selected":false,"text":"true","value":"true"}],"query":"true","skipUrlSync":true,"type":"constant"}]},"time":{"from":"now-5m","to":"now"},"timepicker":{"hidden":true,"refresh_intervals":[]},"timezone":"browser","title":"HOME","uid":"a7bb848c-1ecc-45a0-9d28-cbe05495c66d","version":13}','v0alpha1');
INSERT INTO dashboard_version VALUES(320,34,13,0,14,'2025-12-01 15:54:03',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":34,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":6,"x":0,"y":0},"id":4,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome:text}\");\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (!isHome) {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome) {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/642d6862-e9a1-461d-9a06-85209807bc47/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${keyDiv.dataset.path}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":14,"x":6,"y":0},"id":6,"options":{"afterRender":"","content":"\u003cdiv class=\"container\"\u003e\n  \u003cdiv class=\"header\"\u003e\n    \u003ch1\u003eWhat is TED?\u003c/h1\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"content\"\u003e\n    \u003cp\u003e\n      Telescope Engineering Data (TED) is a system for ingesting, storing, and viewing logs from numerous subsystems and\n      combining them with the telemetry data, all from the Gemini telescope. It provides a web interface based on\n      Grafana\n      software to visualize all data. Grafana is an open-source software that offers to create dashboards with\n      information\n      coming from multiple sources.\n    \u003c/p\u003e\n    \u003cp\u003e\n      In our case, we use 2 sources of data for TED Visualization:\n      - Logs: Logs are loaded from ASCII files and stored in Elasticsearch.\n      - Telemetry: Data is archived by the Archiver Appliance and retrieved using a helper python service\n    \u003c/p\u003e\n    \u003cp\u003e\n      We are committed to enhancing your user experience and providing a valuable tool for your work. Thank you for\n      being\n      part\n      of this journey. If you have any doubts or need further assistance, feel free to contact us in Slack or via email:\n      oscar.fuentes@noirlab.edu\n    \u003c/p\u003e\n    \u003c!-- Logos side by side with HTML and inline CSS --\u003e\n    \u003cdiv style=\"display: flex; justify-content: center; padding-top: 0%;\"\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo073.png\" alt=\"NOIRLab Logo\" style=\"max-width: 100%; width: 600px; margin: 10px;\" /\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo018.png\" alt=\"Gemini Observatory Logo\" style=\"max-width: 100%; width: 300px; margin: 10px;\" /\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"footer\"\u003e\u003cstrong\u003eVersion: 3.0.0\u003c/strong\u003e\u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles","default"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"\u0026{\n  position: relative;\n  display: flex;\n\n}\n.container {\n  padding: 20px;\n  position: fixed;\n  display: grid;\n  min-height:98%;\n  min-width: 99%;\n  grid-template-rows: auto 1fr auto;\n}\n\n.header{\n}\n\n.content{\n  display: flex;\n  flex-direction: column;\n}\n\n.footer{\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":4,"x":20,"y":0},"id":5,"options":{"afterRender":"","content":"\u003cdiv class=\"buttons-container\"\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eGeneral Dashboards\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/eikCiqgvg?orgId=1\" class=\"button-link\"\u003e\n      Telemetry\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/b8j_m3gDR?orgId=1\" class=\"button-link\"\u003e\n      Logs Only\n    \u003c/a\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eDaily Reports\u003c/h2\u003e\n    \u003chr\u003e\n    \u003cdiv class=\"horizontal-section\"\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Environment\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Seeing Monitor\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Telescope\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        OI\n      \u003c/a\u003e\