INSERT INTO dashboard_version VALUES(342,37,17,0,18,'2025-12-01 17:47:08',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  // const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"New panel","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:*ghost*","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":18}','v0alpha1');
INSERT INTO dashboard_version VALUES(343,37,18,0,19,'2025-12-01 17:47:17',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"New panel","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:*ghost*","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":19}','v0alpha1');
INSERT INTO dashboard_version VALUES(344,37,19,0,20,'2025-12-01 17:47:51',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:*ghost*","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":20}','v0alpha1');
INSERT INTO dashboard_version VALUES(345,37,20,0,21,'2025-12-01 17:52:05',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"${theme.colors.background.primary}","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:mcs  subsystem:pcs ","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":21}','v0alpha1');
INSERT INTO dashboard_version VALUES(346,37,21,0,22,'2025-12-01 17:52:43',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.background.primary}","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:mcs  subsystem:pcs ","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":22}','v0alpha1');
INSERT INTO dashboard_version VALUES(347,37,22,0,23,'2025-12-01 17:57:02',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:mcs  subsystem:pcs ","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":23}','v0alpha1');
INSERT INTO dashboard_version VALUES(348,37,23,0,24,'2025-12-01 17:59:01',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eTemperature + GWS\u003eWeather Data\u003eHumidity","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"ws:cpHumid","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:seqexec-ng  subsystem:hrwfs  subsystem:mcs  subsystem:pcs  subsystem:scs ","type":"textbox"},{"current":{"text":"","value":""},"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":24}','v0alpha1');
INSERT INTO dashboard_version VALUES(349,37,24,0,25,'2025-12-01 17:59:33',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eTemperature + GWS\u003eWeather Data\u003eHumidity","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"ws:cpHumid","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:seqexec  subsystem:seqexec-ng  subsystem:gcal  subsystem:hrwfs  subsystem:mcs  subsystem:pcs  subsystem:scs ","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":25}','v0alpha1');
INSERT INTO dashboard_version VALUES(350,37,25,0,26,'2025-12-01 17:59:59',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"Logs","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:seqexec  subsystem:seqexec-ng  subsystem:gcal  subsystem:hrwfs  subsystem:mcs  subsystem:pcs  subsystem:scs ","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":26}','v0alpha1');
INSERT INTO dashboard_version VALUES(351,37,26,0,27,'2025-12-01 18:01:35',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:seqexec  subsystem:seqexec-ng  subsystem:gcal  subsystem:hrwfs  subsystem:mcs  subsystem:pcs  subsystem:scs ","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":27}','v0alpha1');
INSERT INTO dashboard_version VALUES(352,37,27,0,28,'2025-12-01 18:02:04',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"},"hide":2,"name":"title","options":[{"selected":true,"text":"ECS\u003eTop Shutter\u003eDemand","value":"ECS\u003eTop Shutter\u003eDemand"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["cr:crCWP:PmacPosError"],"value":["cr:crCWP:PmacPosError"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper"],"value":["casnooper"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"","value":""}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":28}','v0alpha1');
INSERT INTO dashboard_version VALUES(353,37,28,0,29,'2025-12-01 18:02:10',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpTemp50m"],"value":["ws:cpTemp50m"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"],"value":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"msg:**","value":"msg:**"},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"msg:**","value":"msg:**"}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":29}','v0alpha1');
INSERT INTO dashboard_version VALUES(354,37,29,0,30,'2025-12-01 18:08:06',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n  gap:2%;\n  padding: 1%;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpTemp50m"],"value":["ws:cpTemp50m"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"],"value":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"msg:**","value":"msg:**"},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"msg:**","value":"msg:**"}],"query":"msg:**","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"","value":""}],"query":"subsystem:seqexec-ng ","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":30}','v0alpha1');
INSERT INTO dashboard_version VALUES(355,37,30,0,31,'2025-12-01 18:08:19',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":37,"links":[],"panels":[{"gridPos":{"h":32,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":14,"w":19,"x":5,"y":18},"id":7,"options":{"afterRender":"console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\nconsole.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n\n\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n\n \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});\n\nconsole.log(\"Before\");\n\n\n","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n  gap:2%;\n  padding: 1%;\n}\n.actions {\n  background-color: ${theme.colors.background.canvas}\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.secondary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 70%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 10vw;\n  min-width: 10vw;\n  width: 10%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  position: fixed;\n  top:2%;\n  right: 2%;\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eTemperature","value":"GWS\u003eWeather Data\u003eTemperature"}],"query":"GWS\u003eWeather Data\u003eTemperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpTemp50m"],"value":["ws:cpTemp50m"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"},{"current":{"text":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"],"value":["casnooper","dhs","gacq","gea-archivedaemon","gea-error","gea-watcher","ghost-cicada","ghost-gmp-server","gws","ltts","qpt","seqexec","seqexec-ng","tcc","tcs","vii","ot","ag","ang-rtems","aom","bto","crcs","ecs","f2oiwfs","flam2sparc","flamingos-2","gcal","gis","gmos-perle-cc","gmos-perle-dc","gsaoi-cc","gsaoi-dc","gsaoi-perle-cc","gsaoi-perle-dc","hrwfs","mcs","oiwfs","pcs","prcs","pwfs1","pwfs2","scs"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"X9mrkFjVk"},"definition":"","hide":2,"label":"Subsystems for Logs","multi":true,"name":"logs_subsystem_aux","options":[],"query":{"cacheDurationSeconds":300,"fields":[{"jsonPath":"$.data_streams[*].name"}],"method":"GET","queryParams":"","urlPath":"/_data_stream"},"refresh":1,"regex":"^(?:[^-]+-){2}(.+)$","type":"query"},{"current":{"text":"","value":""},"hide":2,"label":"Lucene Query","name":"lucene_query","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"msg:**","value":"msg:**"},"hide":2,"label":"Search message","name":"search_message","options":[{"selected":true,"text":"msg:**","value":"msg:**"}],"query":"msg:**","type":"textbox"},{"current":{"text":"subsystem:seqexec-ng ","value":"subsystem:seqexec-ng "},"hide":2,"name":"logs_subsystem","options":[{"selected":true,"text":"subsystem:seqexec-ng ","value":"subsystem:seqexec-ng "}],"query":"subsystem:seqexec-ng ","type":"textbox"},{"current":{"text":"","value":""},"hide":2,"name":"search_message_aux","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry + Logs","uid":"ccde8494-7209-4abf-b0ff-d722a6abf3a6","version":31}','v0alpha1');
INSERT INTO dashboard_version VALUES(356,34,14,0,15,'2025-12-01 18:08:38',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":34,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":6,"x":0,"y":0},"id":4,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome:text}\");\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (!isHome) {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome) {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/ccde8494-7209-4abf-b0ff-d722a6abf3a6/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${keyDiv.dataset.path}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":14,"x":6,"y":0},"id":6,"options":{"afterRender":"","content":"\u003cdiv class=\"container\"\u003e\n  \u003cdiv class=\"header\"\u003e\n    \u003ch1\u003eWhat is TED?\u003c/h1\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"content\"\u003e\n    \u003cp\u003e\n      Telescope Engineering Data (TED) is a system for ingesting, storing, and viewing logs from numerous subsystems and\n      combining them with the telemetry data, all from the Gemini telescope. It provides a web interface based on\n      Grafana\n      software to visualize all data. Grafana is an open-source software that offers to create dashboards with\n      information\n      coming from multiple sources.\n    \u003c/p\u003e\n    \u003cp\u003e\n      In our case, we use 2 sources of data for TED Visualization:\n      - Logs: Logs are loaded from ASCII files and stored in Elasticsearch.\n      - Telemetry: Data is archived by the Archiver Appliance and retrieved using a helper python service\n    \u003c/p\u003e\n    \u003cp\u003e\n      We are committed to enhancing your user experience and providing a valuable tool for your work. Thank you for\n      being\n      part\n      of this journey. If you have any doubts or need further assistance, feel free to contact us in Slack or via email:\n      oscar.fuentes@noirlab.edu\n    \u003c/p\u003e\n    \u003c!-- Logos side by side with HTML and inline CSS --\u003e\n    \u003cdiv style=\"display: flex; justify-content: center; padding-top: 0%;\"\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo073.png\" alt=\"NOIRLab Logo\" style=\"max-width: 100%; width: 600px; margin: 10px;\" /\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo018.png\" alt=\"Gemini Observatory Logo\" style=\"max-width: 100%; width: 300px; margin: 10px;\" /\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"footer\"\u003e\u003cstrong\u003eVersion: 3.0.0\u003c/strong\u003e\u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles","default"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"\u0026{\n  position: relative;\n  display: flex;\n\n}\n.container {\n  padding: 20px;\n  position: fixed;\n  display: grid;\n  min-height:98%;\n  min-width: 99%;\n  grid-template-rows: auto 1fr auto;\n}\n\n.header{\n}\n\n.content{\n  display: flex;\n  flex-direction: column;\n}\n\n.footer{\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":4,"x":20,"y":0},"id":5,"options":{"afterRender":"","content":"\u003cdiv class=\"buttons-container\"\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eGeneral Dashboards\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/eikCiqgvg?orgId=1\" class=\"button-link\"\u003e\n      Telemetry\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/b8j_m3gDR?orgId=1\" class=\"button-link\"\u003e\n      Logs Only\n    \u003c/a\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eDaily Reports\u003c/h2\u003e\n    \u003chr\u003e\n    \u003cdiv class=\"horizontal-section\"\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Environment\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Seeing Monitor\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Telescope\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        OI\n      \u003c/a\u003e\