INSERT INTO dashboard_version VALUES(446,36,1,0,2,'2025-12-09 15:47:51',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":36,"links":[],"panels":[{"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":"","type":"library-panel-ref"},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":28,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"font":{"color":"black","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"}],"preload":false,"refresh":"","schemaVersion":41,"tags":[],"templating":{"list":[{"current":{"text":"GWS \u003e Weather Data \u003e Temperature","value":"GWS \u003e Weather Data \u003e Temperature"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS \u003e Weather Data \u003e Temperature","value":"GWS \u003e Weather Data \u003e Temperature"}],"query":"GWS \u003e Weather Data \u003e Temperature","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpTemp50m"],"value":["ws:cpTemp50m"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[{"selected":true,"text":"First Fill","value":"firstFill"},{"selected":false,"text":"Mean","value":"mean"},{"selected":false,"text":"Median","value":"median"}],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[{"selected":true,"text":"subsystems","value":"subsystems"},{"selected":false,"text":"instruments","value":"instruments"}],"query":"subsystems, instruments","type":"custom"}]},"time":{"from":"now-12h","to":"now"},"timepicker":{"refresh_intervals":["1s","5s","10s","30s","1m","5m","15m","30m","1h","2h","1d"]},"timezone":"browser","title":"Telemetry","uid":"642d6862-e9a1-461d-9a06-85209807bc47","version":2}','v0alpha1');
INSERT INTO dashboard_version VALUES(447,34,22,0,23,'2025-12-11 19:11:35',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":34,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":6,"x":0,"y":0},"id":4,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome:text}\");\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n\n    console.log(treeNode.querySelector(''.key''));\n\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (!isHome) {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome) {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/ccde8494-7209-4abf-b0ff-d722a6abf3a6/telemetry?orgId=1\u0026from=now-3h\u0026to=now\u0026timezone=browser\u0026var-title=${keyDiv.dataset.path}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.className = ''key-text'';\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":14,"x":6,"y":0},"id":6,"options":{"afterRender":"","content":"\u003cdiv class=\"container\"\u003e\n  \u003cdiv class=\"header\"\u003e\n    \u003ch1\u003eWhat is TED?\u003c/h1\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"content\"\u003e\n    \u003cp\u003e\n      Telescope Engineering Data (TED) is a system for ingesting, storing, and viewing logs from numerous subsystems and\n      combining them with the telemetry data, all from the Gemini telescope. It provides a web interface based on\n      Grafana\n      software to visualize all data. Grafana is an open-source software that offers to create dashboards with\n      information\n      coming from multiple sources.\n    \u003c/p\u003e\n    \u003cp\u003e\n      In our case, we use 2 sources of data for TED Visualization:\n      - Logs: Logs are loaded from ASCII files and stored in Elasticsearch.\n      - Telemetry: Data is archived by the Archiver Appliance and retrieved using a helper python service\n    \u003c/p\u003e\n    \u003cp\u003e\n      We are committed to enhancing your user experience and providing a valuable tool for your work. Thank you for\n      being\n      part\n      of this journey. If you have any doubts or need further assistance, feel free to contact us in Slack or via email:\n      oscar.fuentes@noirlab.edu\n    \u003c/p\u003e\n    \u003c!-- Logos side by side with HTML and inline CSS --\u003e\n    \u003cdiv class=\"images\"\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo073.png\" alt=\"NOIRLab Logo\" style=\"max-width: 100%; width: 600px; margin: 10px;\" /\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo018.png\" alt=\"Gemini Observatory Logo\" style=\"max-width: 100%; width: 300px; margin: 10px;\" /\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"footer\"\u003e\u003cstrong\u003eVersion: 3.0.0\u003c/strong\u003e\u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles","default"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"\u0026{\n  position: relative;\n  display: flex;\n\n}\n.container {\n  padding: 20px;\n  position: fixed;\n  display: grid;\n  min-height:98%;\n  min-width: 99%;\n  grid-template-rows: auto 1fr auto;\n}\n\n.header{\n}\n\n.content{\n  display: flex;\n  flex-direction: column;\n}\n\n.footer{\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":4,"x":20,"y":0},"id":5,"options":{"afterRender":"","content":"\u003cdiv class=\"buttons-container\"\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eGeneral Dashboards\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/1DDBK0ZDR?orgId=1\" class=\"button-link\"\u003e\n      Telemetry\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/b8j_m3gDR?orgId=1\" class=\"button-link\"\u003e\n      Logs Only\n    \u003c/a\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eDaily Reports\u003c/h2\u003e\n    \u003chr\u003e\n    \u003cdiv class=\"horizontal-section\"\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Environment\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Seeing Monitor\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Telescope\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        OI\n      \u003c/a\u003e\n    \u003c/div\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Plan of the week\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Weekly Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Fault Reports\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Nightlog\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eCompilations\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Calibrations\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      IQ\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Temporary\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Versions\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eReal Time\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Time Probe\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Health\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eExternal Links\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Queue Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Phone Numbers\n    \u003c/a\u003e\n    \u003ca href=\"https://www.gemini.edu/\" class=\"button-link\"\u003e\n      Gemini Home\n    \u003c/a\u003e\n    \u003ca href=\"https://opswiki.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      OPS Wiki\n    \u003c/a\u003e\n    \u003ca href=\"http://swg.wikis-internal.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      SWG Wiki\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"  \u0026{\n    // background-color:${theme.colors.background.canvas};\n  }\n  .buttons-container {\n    display: flex;\n    justify-content: left;\n    align-items: center;\n    flex-direction: column;\n  }\n  \n  .button-section{\n    width: 100%;\n    // background-color:${theme.colors.background.canvas};\n    padding:20px;\n  }\n  .button-disabled{\n    pointer-events: none;\n    cursor: not-allowed;\n    color: gray !important;\n  }\n\n  .horizontal-section{\n    display: flex;\n    gap: 10px;\n  }\n\n  .button-link {\n    display: flex;\n    font-size: 1vh;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    width: 100%;\n    padding: 1%;\n    margin-bottom: 1%;\n    background-color: ${theme.colors.background.secondary};\n    color: ${theme.colors.text.primary};\n    text-decoration: none;\n    border: none;\n    border-radius: 5px;\n    cursor: pointer;\n  }\n  .button-link:hover{\n    background-color: ${theme.colors.background.canvas};\n    color: ${theme.colors.text.link};\n  }","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"}],"preload":false,"schemaVersion":41,"tags":[],"templating":{"list":[{"allowCustomValue":false,"current":{"text":"subsystems","value":"subsystems"},"description":"","hide":2,"label":"Category","name":"pvTreeCategory","options":[{"selected":false,"text":"Instruments","value":"instruments"},{"selected":true,"text":"Subsystems","value":"subsystems"}],"query":"Instruments : instruments, Subsystems : subsystems","type":"custom"},{"current":{"text":"true","value":"true"},"description":"","hide":2,"name":"isHome","options":[{"selected":false,"text":"true","value":"true"}],"query":"true","skipUrlSync":true,"type":"constant"}]},"time":{"from":"now-1h","to":"now"},"timepicker":{"hidden":true,"refresh_intervals":[]},"timezone":"browser","title":"HOME","uid":"a7bb848c-1ecc-45a0-9d28-cbe05495c66d","version":23}','v0alpha1');
INSERT INTO dashboard_version VALUES(448,34,23,0,24,'2025-12-11 19:12:18',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":0,"id":34,"links":[],"panels":[{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":6,"x":0,"y":0},"id":4,"options":{"afterRender":"const isHome = context.grafana.replaceVariables(\"${isHome:text}\");\n\nconst container = document.getElementById(''pvTree'');\nif (container) container.innerHTML = \"\";\n\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\nconst catBtns = document.getElementsByClassName(''catBtn'');\n\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expand-icon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\n\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n\nconst searchInput = document.getElementById(''treeSearch'');\n\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''pvTreeSearch'', term);\n  filterTree(container, term);\n});\n\nfunction filterTree(root, searchTerm) {\n  const term = searchTerm.toLowerCase().trim();\n  // Recursively check a tree wrapper\n  function checkTree(treeNode) {\n    let match = false;\n    // Check leaf inside tree\n    const leaf = treeNode.querySelector(''.leaf'');\n    if (leaf) {\n      const name = leaf.querySelector(''.nameText'').textContent.toLowerCase();\n      match = name.includes(term);\n      leaf.style.display = match ? '''' : ''none'';\n    }\n\n    console.log(treeNode.querySelector(''.key''));\n\n    // Check children container\n    const childrenContainer = treeNode.querySelector(''.children'');\n    if (childrenContainer) {\n      const childTrees = Array.from(childrenContainer.children);\n      let childMatch = false;\n      childTrees.forEach(child =\u003e {\n        if (child.classList.contains(''tree'')) {\n          const childResult = checkTree(child);\n          if (childResult) childMatch = true;\n        }\n      });\n      // Show children container if any child matches\n      childrenContainer.classList.toggle(''hidden'', !childMatch);\n      // Update icon\n      const icon = treeNode.querySelector(''.expand-icon'');\n      if (icon) icon.textContent = childMatch ? ''▼'' : ''▶'';\n      if (childMatch) match = true;\n    }\n    // Show or hide tree wrapper itself\n    treeNode.style.display = match ? '''' : ''none'';\n    return match;\n  }\n  Array.from(root.children).forEach(treeNode =\u003e {\n    if (treeNode.classList.contains(''tree'')) {\n      checkTree(treeNode);\n    }\n  });\n}\n\n\n\n\n// This is for action buttons on each tree leaf item\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, parent));\n  parent.appendChild(btn);\n}\n\nfunction buildTree(obj, container, path = []) {\n  for (const key in obj) {\n    const currentPath = [...path, key];\n\n    // If have codes, is clickeable leaf\n    if (''codes'' in obj[key]) {\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''leaf'';\n      const nameText = document.createElement(''div'');\n      nameText.textContent = key;\n      nameText.className = ''nameText'';\n      keyDiv.appendChild(nameText);\n\n      // Button holder\n      const btnHolder = document.createElement(''div'');\n      btnHolder.className = ''btnHolder'';\n      keyDiv.appendChild(btnHolder);\n\n      //BUTTONS\n      //Append Button\n      if (!isHome) {\n        createButton(btnHolder, ''leafBtn'', ''+L'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n            if (selectedExtraAxisPVs.includes(code)) {\n              selectedExtraAxisPVs = selectedExtraAxisPVs.filter(c =\u003e c != code);\n              context.grafana.locationService.partial({\n                ''var-pvExtraAxis'': selectedExtraAxisPVs\n              }, true);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + \\n ${keyDiv.dataset.path}`,\n          }, true);\n        })\n        //Append (w extra axis) Button\n        createButton(btnHolder, ''leafBtn'', ''+R'', (e, parent) =\u003e {\n          e.stopPropagation();\n          let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n\n          const arrCodes = JSON.parse(parent.parentElement.dataset.codes);\n          let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n          let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n          // Adding to pv to query\n          for (const code of arrCodes) {\n            if (!selectedPVs.includes(code)) {\n              selectedPVs.push(code);\n            }\n          }\n          context.grafana.locationService.partial({\n            ''var-pv'': selectedPVs,\n            ''var-title'': currentTitle.includes(keyDiv.dataset.path) ? currentTitle : `${currentTitle} + ${keyDiv.dataset.path}`,\n          }, true);\n\n\n          if (selectedExtraAxisPVs[0] == \"\") {\n            selectedExtraAxisPVs = arrCodes;\n          }\n          else {\n            selectedExtraAxisPVs.push(...arrCodes);\n          }\n\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n          }, true);\n        })\n      }\n      // Div Channel Name\n\n      keyDiv.dataset.codes = JSON.stringify(obj[key][\"codes\"]);\n      keyDiv.dataset.path = currentPath.join(\"\u003e\");\n      keyDiv.addEventListener(\"click\", () =\u003e {\n        const arrCodes = JSON.parse(keyDiv.dataset.codes);\n        if (isHome) {\n          const codesParam = arrCodes.map(code =\u003e `var-pv=${code}`);\n          const codesParamStr = codesParam.join(\"\u0026\");\n          // console.log(\"Path:\", path.join(\" → \"));\n          // console.log(\"Codes:\", codesParamStr);\n          window.location.href = `http://ted-dev.cl.gemini.edu/d/ccde8494-7209-4abf-b0ff-d722a6abf3a6/telemetry?orgId=1\u0026from=now-3h\u0026to=now\u0026timezone=browser\u0026var-title=${keyDiv.dataset.path}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n        }\n        else {\n          context.grafana.locationService.partial({\n            ''var-pv'': arrCodes,\n            ''var-title'': keyDiv.dataset.path\n          }, true);\n          context.grafana.locationService.partial({\n            ''var-pvExtraAxis'': ''''\n          }, true);\n        }\n      });\n\n      wrapper.appendChild(keyDiv);\n      container.appendChild(wrapper);\n\n    } else {\n      // Create Section\n      const value = obj[key];\n      const wrapper = document.createElement(''div'');\n      wrapper.className = ''tree'';\n      const keyDiv = document.createElement(''div'');\n      keyDiv.className = ''key'';\n      const expandIcon = document.createElement(''span'');\n      const nodePath = currentPath.join(\" \u003e \");\n      const isExpanded = localStorage.getItem(`treeExpanded:${nodePath}`) === \"true\";\n      expandIcon.textContent = isExpanded ? ''▼'' : ''▶'';\n      expandIcon.className = ''expand-icon'';\n      keyDiv.appendChild(expandIcon);\n      const keyText = document.createElement(''span'');\n      keyText.className = ''key-text'';\n      keyText.textContent = ` ${key}`;\n      keyDiv.appendChild(keyText);\n      const childrenContainer = document.createElement(''div'');\n      childrenContainer.className = ''children'';\n      if (!isExpanded) {\n        childrenContainer.classList.add(''hidden'');\n      }\n\n      if (typeof value === ''object'' \u0026\u0026 value !== null) {\n        buildTree(value, childrenContainer, currentPath);\n\n        keyDiv.addEventListener(\"click\", () =\u003e {\n          const isHidden = childrenContainer.classList.toggle(''hidden'');\n          expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n          localStorage.setItem(`treeExpanded:${nodePath}`, (!isHidden).toString());\n        });\n      }\n\n      wrapper.appendChild(keyDiv);\n      wrapper.appendChild(childrenContainer);\n      container.appendChild(wrapper);\n    }\n  }\n}\n\nbuildTree(data, container);\n\nsearchInput.value = localStorage.getItem(''pvTreeSearch'');\nconst term = searchInput.value.toLowerCase().trim();\nif (term != \"\") {\n  filterTree(container, term);\n}\n","content":"\u003cdiv class=\"categoriesContainer\"\u003e\n  \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n  \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n\u003c/div\u003e\n\u003chr /\u003e\n\u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n\u003chr /\u003e\n\u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* Top Action Buttons */\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n#treeSearch {\n  width: 100%;\n}\n\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color:  ${theme.colors.primary.main};\n}\n\n/* Base Tree */\n.tree {\n  width: 100%;\n  font-family: monospace;\n  background-color: ${theme.colors.background.primary};\n}\n\n.hidden {\n  display: none;\n}\n\n/* Sections */\n.key {\n  font-weight: 600;\n  color: ${theme.colors.text.primary};\n  padding: 4px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background-color 0.2s ease;\n}\n\n.key:hover {\n  color:  ${theme.colors.primary.main}\n}\n\n.children { \n  margin-left: 20px;\n}\n\n.expand-icon {\n  display: inline-block;\n  width: 14px;\n  text-align: center;\n}\n\n/* Leafs */\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 20px;\n}\n\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n\n.leaf:hover .nameText {\n  color: ${theme.colors.primary.main}\n}\n\n.leaf:hover .btnHolder {\n  display: inline-flex;\n}\n\n.nameText {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n  transition: background-color 0.2s ease;\n}\n\n.btnHolder {\n  display: none;\n  width: 100px;\n  height: 20px;\n  justify-content: right;\n  align-items: center;\n}\n\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":5,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"Channel Selector","type":"marcusolsson-dynamictext-panel"},{"datasource":{"uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":14,"x":6,"y":0},"id":6,"options":{"afterRender":"","content":"\u003cdiv class=\"container\"\u003e\n  \u003cdiv class=\"header\"\u003e\n    \u003ch1\u003eWhat is TED?\u003c/h1\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"content\"\u003e\n    \u003cp\u003e\n      Telescope Engineering Data (TED) is a system for ingesting, storing, and viewing logs from numerous subsystems and\n      combining them with the telemetry data, all from the Gemini telescope. It provides a web interface based on\n      Grafana\n      software to visualize all data. Grafana is an open-source software that offers to create dashboards with\n      information\n      coming from multiple sources.\n    \u003c/p\u003e\n    \u003cp\u003e\n      In our case, we use 2 sources of data for TED Visualization:\n      - Logs: Logs are loaded from ASCII files and stored in Elasticsearch.\n      - Telemetry: Data is archived by the Archiver Appliance and retrieved using a helper python service\n    \u003c/p\u003e\n    \u003cp\u003e\n      We are committed to enhancing your user experience and providing a valuable tool for your work. Thank you for\n      being\n      part\n      of this journey. If you have any doubts or need further assistance, feel free to contact us in Slack or via email:\n      oscar.fuentes@noirlab.edu\n    \u003c/p\u003e\n    \u003c!-- Logos side by side with HTML and inline CSS --\u003e\n    \u003cdiv class=\"images\"\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo073.png\" alt=\"NOIRLab Logo\" style=\"max-width: 100%; width: 600px; margin: 10px;\" /\u003e\n      \u003cimg src=\"https://noirlab.edu/public/media/archives/logos/original_trans/logo018.png\" alt=\"Gemini Observatory Logo\" style=\"max-width: 100%; width: 300px; margin: 10px;\" /\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"footer\"\u003e\u003cstrong\u003eVersion: 3.0.0\u003c/strong\u003e\u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles","default"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"\u0026{\n  position: relative;\n  display: flex;\n\n}\n.container {\n  padding: 20px;\n  position: fixed;\n  display: grid;\n  min-height:98%;\n  min-width: 99%;\n  grid-template-rows: auto 1fr auto;\n}\n\n.header{\n}\n\n.content{\n  display: flex;\n  flex-direction: column;\n}\n\n.images{\n  display: flex;\n  justify-content: center;\n  padding-top: 0%;\n  flex-wrap: wrap;\n}\n.footer{\n}","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"uid":"grafana"},"queryType":"list","refId":"A"}],"title":"","type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"datasource","uid":"grafana"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green"},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":4,"x":20,"y":0},"id":5,"options":{"afterRender":"","content":"\u003cdiv class=\"buttons-container\"\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eGeneral Dashboards\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/1DDBK0ZDR?orgId=1\" class=\"button-link\"\u003e\n      Telemetry\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu/goto/b8j_m3gDR?orgId=1\" class=\"button-link\"\u003e\n      Logs Only\n    \u003c/a\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eDaily Reports\u003c/h2\u003e\n    \u003chr\u003e\n    \u003cdiv class=\"horizontal-section\"\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Environment\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Seeing Monitor\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        Telescope\n      \u003c/a\u003e\n      \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n        OI\n      \u003c/a\u003e\n    \u003c/div\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Plan of the week\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Weekly Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Fault Reports\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Nightlog\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eCompilations\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Calibrations\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      IQ\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Temporary\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Versions\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eReal Time\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Time Probe\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Health\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\n  \u003cdiv class=\"button-section\"\u003e\n    \u003ch2\u003eExternal Links\u003c/h2\u003e\n    \u003chr\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Queue Plan\n    \u003c/a\u003e\n    \u003ca href=\"http://ted-dev.cl.gemini.edu\" class=\"button-disabled button-link\"\u003e\n      Phone Numbers\n    \u003c/a\u003e\n    \u003ca href=\"https://www.gemini.edu/\" class=\"button-link\"\u003e\n      Gemini Home\n    \u003c/a\u003e\n    \u003ca href=\"https://opswiki.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      OPS Wiki\n    \u003c/a\u003e\n    \u003ca href=\"http://swg.wikis-internal.gemini.edu/index.php/Main_Page\" class=\"button-link\"\u003e\n      SWG Wiki\n    \u003c/a\u003e\n  \u003c/div\u003e\n\n\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"  \u0026{\n    // background-color:${theme.colors.background.canvas};\n  }\n  .buttons-container {\n    display: flex;\n    justify-content: left;\n    align-items: center;\n    flex-direction: column;\n  }\n  \n  .button-section{\n    width: 100%;\n    // background-color:${theme.colors.background.canvas};\n    padding:20px;\n  }\n  .button-disabled{\n    pointer-events: none;\n    cursor: not-allowed;\n    color: gray !important;\n  }\n\n  .horizontal-section{\n    display: flex;\n    gap: 10px;\n  }\n\n  .button-link {\n    display: flex;\n    font-size: 1vh;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    width: 100%;\n    padding: 1%;\n    margin-bottom: 1%;\n    background-color: ${theme.colors.background.secondary};\n    color: ${theme.colors.text.primary};\n    text-decoration: none;\n    border: none;\n    border-radius: 5px;\n    cursor: pointer;\n  }\n  .button-link:hover{\n    background-color: ${theme.colors.background.canvas};\n    color: ${theme.colors.text.link};\n  }","wrap":true},"pluginVersion":"5.7.0","targets":[{"datasource":{"type":"datasource","uid":"grafana"},"queryType":"list","refId":"A"}],"title":"