INSERT INTO dashboard_version VALUES(474,47,16,0,17,'2025-12-12 17:16:57',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":47,"links":[],"panels":[{"gridPos":{"h":33,"w":5,"x":0,"y":0},"id":6,"libraryPanel":{"name":"Channel Selector","uid":"bf2n6ddxksr28c"},"title":""},{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"gridPos":{"h":18,"w":19,"x":5,"y":0},"id":5,"options":{"allData":{},"config":{},"data":[],"imgFormat":"png","layout":{"editable":true,"font":{"family":"Inter, Helvetica, Arial, sans-serif","uirevision":true},"hoverlabel":{"bgcolor":"${theme.colors.background.primary}","color":"${theme.colors.text.primary}","font":{"bgcolor":"red","size":12}},"hovermode":"x unified","margin":{"b":0,"l":0,"r":0,"t":30},"title":{"automargin":false,"text":"$variables.title.current.text,"},"tooltip":{"color":"white"},"uirevision":true,"xaxis":{"automargin":true,"autorange":true,"title":"Time","type":"date"},"yaxis":{"automargin":true,"autorange":true},"yaxis2":{"automargin":true,"overlaying":"y","side":"right","title":""}},"onclick":"// Event handling\n/*\n// ''data'', ''variables'', ''options'', ''utils'', and ''event'' are passed as arguments\n\ntry {\n  const { type: eventType, data: eventData } = event;\n  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;\n\n  switch (eventType) {\n    case ''click'':\n      console.log(''Click event:'', eventData.points);\n      break;\n    case ''select'':\n      console.log(''Selection event:'', eventData.range);\n      break;\n    case ''zoom'':\n      console.log(''Zoom event:'', eventData);\n      break;\n    default:\n      console.log(''Unhandled event type:'', eventType, eventData);\n  }\n\n  console.log(''Current time zone:'', timeZone);\n  console.log(''From time:'', dayjs(variables.__from).format());\n  console.log(''To time:'', dayjs(variables.__to).format());\n\n  // Example of using locationService\n  // locationService.partial({ ''var-example'': ''test'' }, true);\n\n} catch (error) {\n  console.error(''Error in onclick handler:'', error);\n}\n*/\n  ","resScale":2,"script":"// console.log(data);\n// console.log(variables);\n// console.log(options);\n\n\nlet series = data.series;\nlet layout = {\n  title: variables.title.current.text,\n  yaxis: {\n    showline: true,\n    title: \"\"\n  },\n  yaxis2: {\n    title: \"\",\n    overlaying: ''y'',\n    side: ''right'',\n  }\n};\n\n\nconst config = {\n  editable:true\n}\n\nif (series[0] != \"no data\"){\n\n\n  let traces = [];\n\n\n  const pvExtraAxis = variables.pvExtraAxis.current.text.split(\",\");\n  series.forEach((s, i) =\u003e {\n\n  let name, x, y;\n  \n  name = s.name;\n  x = Array.from(s.fields[0].values);\n  y = Array.from(s.fields[1].values);\n\n\n  let pvInExtraAxis = pvExtraAxis.some(pv =\u003e pv.includes(name));\n  let targetAxis = pvInExtraAxis ? ''y2'' : ''y1'';\n\n  // Fix single-point issue\n  let traceMode = ''lines'';\n  // if(x.length === 1){\n  //   traceMode = ''lines+markers'';\n\n  //   if(!layout.xaxis) layout.xaxis = {};\n  //   if(!layout.xaxis.range) layout.xaxis.range = [x[0] - 1, x[0] + 1];\n  // }\n\n  traces.push({\n    x: x,\n    y: y,\n    type: ''scatter'',\n    mode: ''lines'',\n    line:{\n      shape:''hv''\n    },\n    name: name,\n    yaxis: targetAxis,\n  });\n\n  if(pvInExtraAxis){\n      layout.yaxis2.title = layout.yaxis2.title ? `${name}, ${layout.yaxis2.title}` : name;\n    } else {\n      layout.yaxis.title = layout.yaxis.title ? `${name}, ${layout.yaxis.title}` : name;\n    }\n  });\n\n  return {\n      data: traces,\n      layout: layout,\n      config: config\n    };\n  }\n\n","syncTimeRange":true,"timeCol":""},"pluginVersion":"1.8.1","targets":[{"cacheDurationSeconds":0,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"experimentalGroupByField":"Channel","experimentalMetricField":"Value","fields":[{"jsonPath":"$.data.(secs*1000+nanos/1000000)","language":"jsonata","name":"Time","type":"time"},{"jsonPath":"$.data.val","language":"jsonata","name":"Value"},{"jsonPath":"$.data.val.%.%.meta.name","language":"jsonata","name":"Channel"}],"method":"GET","params":[["pv","${pv:csv}"],["from","${__from:date}"],["to","${__to:date}"],["pp_mode","${ppType}"],["pp_bin","auto"]],"queryParams":"","refId":"Data","urlPath":"/getPVs"}],"title":" ","type":"nline-plotlyjs-panel"},{"gridPos":{"h":15,"w":19,"x":5,"y":18},"id":7,"libraryPanel":{"name":"Logs","uid":"bf6vynykmyn7kd"},"title":""}],"preload":false,"refresh":"","schemaVersion":42,"tags":[],"templating":{"list":[{"current":{"text":"GWS\u003eWeather Data\u003eWind Speed","value":"GWS\u003eWeather Data\u003eWind Speed"},"hide":2,"name":"title","options":[{"selected":true,"text":"GWS\u003eWeather Data\u003eWind Speed","value":"GWS\u003eWeather Data\u003eWind Speed"}],"query":"GWS\u003eWeather Data\u003eWind Speed","type":"textbox"},{"allValue":"None","allowCustomValue":true,"current":{"text":["ws:cpWindSpeed"],"value":["ws:cpWindSpeed"]},"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"definition":"","includeAll":false,"multi":true,"name":"pv","options":[],"query":{"cacheDurationSeconds":0,"fields":[{"jsonPath":"$.*"}],"method":"GET","queryParams":"","urlPath":"/getAllPVs"},"refresh":1,"regex":"","regexApplyTo":"value","type":"query"},{"current":{"text":"","value":""},"hide":2,"name":"pvExtraAxis","options":[{"selected":true,"text":"","value":""}],"query":"","type":"textbox"},{"current":{"text":"firstFill","value":"firstFill"},"description":"","label":"Mode","name":"ppType","options":[],"query":"First Fill : firstFill, Mean : mean, Median : median","type":"custom"},{"current":{"text":"subsystems","value":"subsystems"},"hide":2,"name":"pvTreeCategory","options":[],"query":"subsystems, inst