INSERT INTO dashboard_version VALUES(537,51,52,0,53,'2025-12-15 12:45:58',1,'','{"annotations":{"list":[{"builtIn":1,"datasource":{"type":"grafana","uid":"-- Grafana --"},"enable":true,"hide":true,"iconColor":"rgba(0, 211, 255, 1)","name":"Annotations \u0026 Alerts","type":"dashboard"}]},"editable":true,"fiscalYearStartMonth":0,"graphTooltip":2,"id":51,"links":[],"panels":[{"datasource":{"type":"sasaki77-archiverappliance-datasource","uid":"cesb7dv10h3i8b"},"fieldConfig":{"defaults":{"color":{"mode":"palette-classic"},"custom":{"axisBorderShow":false,"axisCenteredZero":false,"axisColorMode":"text","axisLabel":"","axisPlacement":"auto","barAlignment":0,"barWidthFactor":0.6,"drawStyle":"line","fillOpacity":0,"gradientMode":"none","hideFrom":{"legend":false,"tooltip":false,"viz":false},"insertNulls":false,"lineInterpolation":"linear","lineWidth":1,"pointSize":5,"scaleDistribution":{"type":"linear"},"showPoints":"auto","showValues":false,"spanNulls":false,"stacking":{"group":"A","mode":"none"},"thresholdsStyle":{"mode":"off"}},"mappings":[],"thresholds":{"mode":"absolute","steps":[{"color":"green","value":0},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":11,"w":13,"x":0,"y":0},"id":8,"options":{"legend":{"calcs":[],"displayMode":"list","placement":"bottom","showLegend":true},"tooltip":{"hideZeros":false,"mode":"single","sort":"none"}},"pluginVersion":"12.4.0-20151846001","targets":[{"alias":"","aliasPattern":"","datasource":{"type":"sasaki77-archiverappliance-datasource","uid":"cesb7dv10h3i8b"},"functions":[],"live":false,"operator":"firstFill","refId":"A","regex":false,"stream":false,"strmCap":"","strmInt":"","target":"ws:cpTemp50m"}],"title":"New panel","type":"timeseries"},{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green","value":0},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":11,"x":13,"y":0},"id":7,"options":{"afterRender":"// console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\n// console.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  // console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      // console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      // console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\n//Load actions visibility on init\nconst actions = document.getElementById(''actions'');\nconst showActions = localStorage.getItem(''showActions'');\nconst isVisible = showActions === null || showActions === ''true'';\nactions.classList.toggle(''hidden'', !isVisible);\nlocalStorage.setItem(''showActions'', isVisible);\n\nfunction toggleActions() {\n  const actions = document.getElementById(''actions'');\n  const showActions = localStorage.getItem(''showActions'') === ''true'';\n  const newState = !showActions;\n  actions.classList.toggle(''hidden'', !newState);\n  localStorage.setItem(''showActions'', newState);\n}\n\ndocument.getElementById(''toggleActions'').addEventListener(''click'', function (event) {\n  event.preventDefault();\n  toggleActions();\n});\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"toggleActions\" id=\"toggleActions\"\u003e\n    \u003ci class=\"fa fa-search\"\u003e\u003c/i\u003e\n  \u003c/div\u003e\n\n \u003cdiv class=\"actions hidden\" id=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n      \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n      \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n      \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n      \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003eNo data\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n  \u003c/table\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"toggleActions\" id=\"toggleActions\"\u003e\n    \u003ci class=\"fa fa-search\"\u003e\u003c/i\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n    \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n    \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n    \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n    \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n  gap:1%;\n  padding: 0.5%;\n}\n.actions {\n  background-color: ${theme.colors.background.secondary};\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.primary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.primary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.toggleActionsContainer{\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  height: 100%;\n  display: flex;\n  align-items: center;\n}\n.toggleActions{\n  min-width: 3vh;\n  height: 100%;\n  // border-radius: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: ${theme.colors.background.secondary};\n\n}\n.toggleActions:hover{\n  min-width: 3vh;\n  width: 3vh;\n  height: 100%;\n  // border-radius: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor:pointer;\n  background-color: ${theme.colors.action.selectedBorder};\n}\n\n.hidden{\n  display: none;\n  width: 0px;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 100%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 6vw;\n  min-width: 6vw;\n  width: 6vw%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  // position: fixed;\n\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@timestamp":"timestamp"}}},{"id":"sortBy","options":{"fields":{},"sort":[{"desc":false,"field":"timestamp"}]}}],"type":"marcusolsson-dynamictext-panel"},{"datasource":{"type":"sasaki77-archiverappliance-datasource","uid":"cesb7dv10h3i8b"},"fieldConfig":{"defaults":{"color":{"mode":"palette-classic"},"custom":{"axisBorderShow":false,"axisCenteredZero":false,"axisColorMode":"text","axisLabel":"","axisPlacement":"auto","barAlignment":0,"barWidthFactor":0.6,"drawStyle":"line","fillOpacity":0,"gradientMode":"none","hideFrom":{"legend":false,"tooltip":false,"viz":false},"insertNulls":false,"lineInterpolation":"linear","lineWidth":1,"pointSize":5,"scaleDistribution":{"type":"linear"},"showPoints":"auto","showValues":false,"spanNulls":false,"stacki