INSERT INTO library_element VALUES(1,1,0,'bf2n6ddxksr28c','Channel Selector',1,'marcusolsson-dynamictext-panel','','{"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"description":"","fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green","value":null},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":28,"w":5,"x":0,"y":0},"id":6,"options":{"afterRender":"// Flag to change behavior when clicked\nconst isHome = context.grafana.replaceVariables(\"${isHome}\");\n\n// Clean HTML on load\nconst rootContainer = document.getElementById(''pvTree'');\nif (rootContainer) rootContainer.innerHTML = \"\";\n\n// Obtain data from source\nconst jsonString = context.data[0][0].pvTree;\nconst data = JSON.parse(jsonString);\n\n// Systems/Instruments categories\nconst catBtns = document.getElementsByClassName(''catBtn'');\nArray.from(catBtns).forEach(catBtn =\u003e {\n  catBtn.addEventListener(\"click\", (e) =\u003e {\n    context.grafana.locationService.partial({\n      ''var-pvTreeCategory'': e.target.textContent.toLowerCase()\n    }, true);\n  });\n})\n\n// Button to collapse tree\nfunction collapseAll() {\n  document.querySelectorAll(''.children'').forEach(el =\u003e {\n    el.classList.add(''hidden'');\n  });\n  document.querySelectorAll(''.expandIcon'').forEach(icon =\u003e {\n    icon.textContent = ''▶'';\n  });\n  Object.keys(localStorage)\n    .filter(k =\u003e k.startsWith(\"treeExpanded:\"))\n    .forEach(k =\u003e localStorage.setItem(k, \"false\"));\n}\nconst collBtn = document.getElementById(''collBtn'');\ncollBtn.addEventListener(\"click\", () =\u003e {\n  collapseAll();\n});\n\n// Search string on tree, if searched term is empty, draw the whole tree\nconst searchInput = document.getElementById(''treeSearch'');\nsearchInput.addEventListener(''input'', () =\u003e {\n  const term = searchInput.value.toLowerCase().trim();\n  localStorage.setItem(''searchedTerm'', term);\n  drawFilteredTree(data, term);\n});\nfunction drawFilteredTree(data, term) {\n  const filtered = filterTreeData(data, term);\n  rootContainer.innerHTML = \"\";\n  buildTree(filtered, rootContainer);\n  if (term !== \"\") {\n    document.querySelectorAll(\".children\").forEach(el =\u003e {\n      el.classList.remove(\"hidden\");\n    });\n    document.querySelectorAll(\".expandIcon\").forEach(el =\u003e {\n      el.textContent = ''▼''\n    });\n  }\n}\nfunction filterTreeData(tree, term) {\n  if (!term) return tree; // return full dataset\n  const result = {};\n  for (const key in tree) {\n    const value = tree[key];\n    const keyMatches = key.toLowerCase().includes(term);\n    // If it''s a leaf\n    if (\"codes\" in value) {\n      if (keyMatches) {\n        result[key] = value; // keep matching leaf\n      }\n      continue;\n    }\n    // It''s a section → recurse\n    const filteredChildren = filterTreeData(value, term);\n    if (keyMatches) {\n      // Section name matches: keep ALL children untouched\n      result[key] = value;\n    } else if (Object.keys(filteredChildren).length \u003e 0) {\n      // No direct match, but children matched → keep only matched children\n      result[key] = filteredChildren;\n    }\n  }\n  return result;\n}\n\n// Plot channel on axis\nconst plotChan = (e, axis, parent) =\u003e {\n  e.stopPropagation();\n  //Obtain current Title\n  let currentTitle = context.grafana.replaceVariables(\"${title:csv}\");\n  //Get codes\n  const codes = JSON.parse(parent.parentElement.dataset.codes);\n  //Get Lists of channels by axis\n  let selectedPVs = context.grafana.replaceVariables(\"${pv:csv}\").split(\",\");\n  let selectedExtraAxisPVs = context.grafana.replaceVariables(\"${pvExtraAxis:csv}\").split(\",\");\n\n  //For each code in the leaf\n  for (const code of codes) {\n\n    if (axis == \"+L\") {\n      //If leaf codes are not in the codes ploted on left append them\n      if (!selectedPVs.includes(code)) {\n        selectedPVs.push(code);\n      }\n    }\n\n    if (axis == \"+R\") {\n      if (!selectedPVs.includes(code)) {\n        selectedPVs.push(code);\n      }\n      if (selectedExtraAxisPVs[0] == \"\") {\n        selectedExtraAxisPVs = codes;\n      }\n      else {\n        if (!selectedExtraAxisPVs.includes(code)) {\n\n          selectedExtraAxisPVs.push(code);\n        }\n      }\n      context.grafana.locationService.partial({\n        ''var-pvExtraAxis'': selectedExtraAxisPVs.join(\",\")\n      }, true);\n    }\n\n  }\n  context.grafana.locationService.partial({\n    ''var-pv'': selectedPVs,\n    ''var-title'': currentTitle.includes(parent.dataset.path) ? currentTitle : `${currentTitle} + \\n ${parent.parentElement.dataset.path}`,\n  }, true);\n}\n\n// This is for action buttons on each leaf\nfunction createButton(parent, className, textContent, eventFunct) {\n  const btn = document.createElement(''div'');\n  btn.className = className;\n  btn.textContent = textContent;\n  btn.addEventListener(\"click\", (e) =\u003e eventFunct(e, textContent, parent));\n  parent.appendChild(btn);\n}\n\n// Create leaf\nfunction createLeaf(container, chanName, codes, path) {\n  const leafContainer = document.createElement(''div'');\n  leafContainer.className = ''leaf''\n  const leafName = document.createElement(''div'');\n  leafName.textContent = `${chanName}`;\n  leafName.className = ''leafName'';\n  leafContainer.appendChild(leafName);\n\n  // if Home, leaf redirect, if not, enable plot buttons\n  if (isHome != \"true\") {\n    const leafBtnContainer = document.createElement(''div'');\n    leafBtnContainer.className = ''leafBtnContainer'';\n    leafContainer.dataset.codes = JSON.stringify(codes);\n    leafContainer.dataset.path = path.join(\" \u003e \");\n    createButton(leafBtnContainer, ''leafBtn'', ''+L'', plotChan);\n    createButton(leafBtnContainer, ''leafBtn'', ''+R'', plotChan)\n    leafContainer.appendChild(leafBtnContainer);\n    leafContainer.addEventListener(''click'', () =\u003e {\n      console.log(codes);\n      context.grafana.locationService.partial({\n        ''var-pv'': codes,\n        ''var-title'': leafContainer.dataset.path\n      }, true);\n      context.grafana.locationService.partial({\n        ''var-pvExtraAxis'': ''''\n      }, true);\n    })\n  }\n  else {\n    const codesParam = codes.map(code =\u003e `var-pv=${code}`);\n    const codesParamStr = codesParam.join(\"\u0026\");\n    const pathParamStr = path.join(\"\u003e\");\n    const dashboardID = \"063032a1-9bfd-4aa0-a7fc-1e79dc1c46ca\" //Change this to redirect to other dashboard\n    window.location.href = `http://ted-dev.cl.gemini.edu/d/${dashboardID}/telemetry?orgId=1\u0026from=now-12h\u0026to=now\u0026timezone=browser\u0026var-title=${pathParamStr}\u0026${codesParamStr}\u0026var-pvExtraAxis=\u0026var-ppType=firstFill\u0026var-ppBin=1`;\n  }\n  container.appendChild(leafContainer);\n}\n\n// createSection HTML\nfunction createSection(container, section, path) {\n  const sectionContainer = document.createElement(''div'');\n  sectionContainer.className = \"sectionContainer\"\n  // Label wrapper\n  const sectionHeader = document.createElement(''div'');\n  sectionHeader.className = ''sectionHeader'';\n  // Add expanded icon\n  const expandIcon = document.createElement(''div'');\n  expandIcon.className = ''expandIcon'';\n  sectionHeader.appendChild(expandIcon);\n  // Add text to container\n  const sectionName = document.createElement(''div'');\n  sectionName.textContent = `${section}`;\n  sectionName.className = \"sectionName\"\n  sectionHeader.appendChild(sectionName);\n  // Create children container\n  const childrenContainer = document.createElement(''div'');\n  childrenContainer.className = ''children'';\n  // Load node state in localStroage (expanded or not)\n  const isExpanded = localStorage.getItem(`treeExpanded:${path}`) === \"true\";\n  if (!isExpanded) {\n    childrenContainer.classList.add(''hidden'');\n    expandIcon.textContent = ''▶'';\n  }\n  else {\n    expandIcon.textContent = ''▼'';\n  }\n\n  // Toggle children visibility on click event\n  sectionHeader.addEventListener(''click'', (e) =\u003e {\n    e.stopPropagation();\n    console.log(path);\n    const isHidden = childrenContainer.classList.toggle(''hidden'');\n    expandIcon.textContent = !isHidden ? ''▼'' : ''▶'';\n    localStorage.setItem(`treeExpanded:${path}`, (!isHidden).toString());\n  })\n  // Append section to parent container\n  sectionContainer.appendChild(sectionHeader);\n  sectionContainer.appendChild(childrenContainer);\n  container.appendChild(sectionContainer);\n  // Return children container \n  return childrenContainer;\n}\n\nfunction buildTree(tree, container, path = []) {\n  // For each key in the JSON\n  for (const node in tree) {\n    const currentPath = [...path, node];\n    // If has \"codes\" then c leaf\n    if (''codes'' in tree[node]) {\n      createLeaf(container, node, tree[node][\"codes\"], currentPath)\n    }\n    // If not, it is just a node\n    else {\n      // console.log(section);\n      childrenContainer = createSection(container, node, currentPath);\n      // build the HTML tree of the section''s children\n      buildTree(tree[node], childrenContainer, currentPath);\n    }\n  }\n}\n\n\n//MAIN\nsearchInput.value = localStorage.getItem(''searchedTerm'');\nconst term = searchInput.value.toLowerCase().trim();\ndrawFilteredTree(data, term);","content":"\u003cdiv class=\"actions\"\u003e\n  \u003cdiv class=\"categoriesContainer\"\u003e\n    \u003cdiv class=\"catBtn\"\u003eSubsystems\u003c/div\u003e\n    \u003cdiv class=\"catBtn\"\u003eInstruments\u003c/div\u003e\n  \u003c/div\u003e\n  \u003chr /\u003e\n  \u003cinput type=\"text\" id=\"treeSearch\" placeholder=\"Search PVs...\"\u003e\n  \u003chr /\u003e\n  \u003cdiv id=\"collBtn\"\u003eCollapse\u003c/div\u003e\n\u003c/div\u003e\n\u003cdiv id=\"pvTree\"\u003e\u003c/div\u003e","contentPartials":[],"defaultContent":"The query didn''t return any results.","editor":{"format":"auto","language":"html"},"editors":["afterRender","styles"],"externalStyles":[],"helpers":"","renderMode":"data","styles":"/* ----------------------------- Top Actions ----------------------------- */\n/* Categories Buttons */\n.actions {\n  height: 14vh;\n  padding: 10px;\n  margin: 0;\n}\n.categoriesContainer {\n  background-color: ${theme.colors.background.primary};\n  display: flex;\n  justify-content: space-around;\n}\n.catBtn {\n  width: 100%;\n  padding: 1%;\n  cursor: pointer;\n  justify-content: center;\n  text-align: center;\n  background-color: ${theme.colors.background.secondary};\n}\n.catBtn:hover {\n  padding: 1%;\n  cursor: pointer;\n  color: ${theme.colors.background.primary};\n  background-color: ${theme.colors.primary.main};\n}\n/* Search Textbox */\n#treeSearch {\n  width: 100%;\n}\n/* Search Textbox */\n#collBtn {\n  width: 100%;\n  background-color: ${theme.colors.background.secondary};\n  color: ${theme.colors.text.primary};\n  padding: 5px;\n  text-align: center;\n  cursor: pointer;\n}\n#collBtn:hover {\n  color: ${theme.colors.background.primary};\n  background-color: ${theme.colors.primary.main};\n}\n/* ----------------------------- Tree ----------------------------------- */\n\n#pvTree {\n  width: 100%;\n  height: 65vh;\n  margin: 0px;\n  padding: 10px;\n  font-family: monospace;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary};\n}\n.sectionContainer {\n  border-width: 20px !important;\n  border-color: black;\n  margin-bottom: 5px;\n  font-family: monospace;\n  cursor:pointer;\n}\n.sectionHeader {\n  display: flex\n}\n.sectionName {\n  font-weight: bold;\n  width: 100%;\n  margin-left: 0.5%;\n}\n.sectionName:hover {\n  color: ${theme.colors.primary.main}\n}\n.expandIcon {\n  display: inline-block;\n  text-align: center;\n}\n\n.hidden {\n  display: none;\n}\n\n.children { \n  margin-left: 20px;\n}\n.leaf {\n  border-left:dashed;\n  border-radius: 2px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0px 10px;\n}\n.leaf:hover {\n  background-color: ${theme.colors.background.secondary};\n  cursor: pointer;\n}\n.leafName {\n  color: ${theme.colors.text.primary};\n  font-weight: bold;\n  cursor: pointer;\n  padding: 1px;\n}\n.leaf:hover .leafName {\n  color: ${theme.colors.primary.main}\n}\n.leafBtnContainer {\n  display: none;\n  gap: 0.5vh;\n  // background-color: red;\n}\n.leaf:hover .leafBtnContainer {\n  display: inline-flex;\n}\n.leafBtn {\n  display: flex;\n  padding: 0;\n  width: 20px;\n  height: 20px;\n  margin-right: 5px;\n  border-radius: 2px;\n  background-color: ${theme.colors.background.primary};\n  color: ${theme.colors.primary.main};\n  font-size: 15px;\n  font-weight: bold;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: background-color 0.2s ease;\n}\n.leafBtn:hover {\n  background-color:  ${theme.colors.primary.main};\n  color: ${theme.colors.text.primary};\n}\n\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"cacheDurationSeconds":300,"datasource":{"type":"marcusolsson-json-datasource","uid":"aepy5iqt7ke80c"},"fields":[{"jsonPath":"$.","name":"pvTree"}],"method":"GET","params":[["category","${pvTreeCategory}"]],"queryParams":"","refId":"PvTree","urlPath":"/getPvTree"}],"title":"","type":"marcusolsson-dynamictext-panel"}','2025-10-30 20:17:43',1,'2025-12-09 15:47:02',1,7,'general');
INSERT INTO library_element VALUES(2,1,0,'bf6vynykmyn7kd','Logs',1,'logs','','{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"description":"","fieldConfig":{"defaults":{},"overrides":[]},"gridPos":{"h":15,"w":19,"x":5,"y":18},"id":7,"options":{"dedupStrategy":"numbers","detailsMode":"sidebar","enableInfiniteScrolling":true,"enableLogDetails":true,"fontSize":"default","prettifyLogMessage":true,"showControls":true,"showLabels":true,"showTime":true,"sortOrder":"Ascending","syntaxHighlighting":false,"wrapLogMessage":false},"pluginVersion":"12.4.0-20151846001","targets":[{"alias":"","bucketAggs":[],"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"metrics":[{"id":"1","settings":{"limit":"10000"},"type":"logs"}],"query":"","refId":"A","timeField":"@timestamp"}],"title":"","type":"logs"}','2025-12-12 15:56:28',1,'2025-12-12 17:24:30',1,4,'general');
INSERT INTO library_element VALUES(3,1,0,'bf76bajy4uebka','LogsTable',1,'marcusolsson-dynamictext-panel','','{"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"description":"","fieldConfig":{"defaults":{"thresholds":{"mode":"absolute","steps":[{"color":"green","value":null},{"color":"red","value":80}]}},"overrides":[]},"gridPos":{"h":33,"w":11,"x":13,"y":0},"id":7,"options":{"afterRender":"// console.log(context);\nconst allSystems = context.grafana.replaceVariables(\"${logs_subsystem_aux:csv}\");\n// console.log(allSystems);\nconst systemSelector = document.getElementById(\"systemSelector\");\nconst selectedSystems = context.grafana.replaceVariables(\"${logs_subsystem:text}\");\n\nif (systemSelector != null) {\n  const systemList = allSystems.split(\",\");\n  // console.log(systemList);\n  systemSelector.innerHTML = \"\";\n  systemList.map(system =\u003e {\n    const containerDiv = document.createElement(''div'');\n    containerDiv.className = \"logsSystemContainer\";\n    const checkbox = document.createElement(''input'');\n    checkbox.type = ''checkbox'';\n    checkbox.value = system;\n    checkbox.name = ''system'';\n    const label = document.createElement(''label'');\n    label.className = \"logsSystemLabel\";\n    label.textContent = system;\n    if (selectedSystems.includes(system)) {\n      checkbox.checked = true;\n    }\n    containerDiv.appendChild(checkbox);\n    containerDiv.appendChild(label);\n    systemSelector.appendChild(containerDiv);\n  })\n\n  const checkboxes = document.querySelectorAll(''input[name=\"system\"]'');\n  checkboxes.forEach(checkbox =\u003e {\n    checkbox.addEventListener(''change'', () =\u003e {\n      // console.log(checkboxes)\n      selectedList = [];\n      Array.from(checkboxes).map(checkbox =\u003e {\n        subsystem = checkbox.value;\n        if (checkbox.checked == true \u0026\u0026 !selectedList.includes(subsystem)) {\n          selectedList.push(subsystem);\n        }\n      })\n      // console.log(selectedList);\n      context.grafana.locationService.partial(\n        {\n          ''var-logs_subsystem'': selectedList.map(selected =\u003e `subsystem:${selected} `).join(\" \"),\n        },\n        true\n      )\n\n    });\n  });\n}\n\nconst input = document.getElementById(\"searchMsgInput\");\nconst auxMsg = context.grafana.replaceVariables(\"${search_message_aux:text}\");\n\ninput.value = auxMsg;\n\nsearchMsg = () =\u003e {\n  const input = document.getElementById(\"searchMsgInput\").value;\n  const inputList = input.split(\" \");\n\n  let stringToSearch = \"\"\n  if (input == \"\") {\n    stringToSearch = \"msg:**\"\n  }\n  else {\n    for (let element of inputList) {\n      if ([\"AND\", \"OR\", \"NOT\", \"(\", \")\"].some(logicOperator =\u003e element.includes(logicOperator))) {\n        stringToSearch += element;\n      }\n      else {\n        stringToSearch += `msg:*${element}*`\n      }\n      stringToSearch += \" \";\n    }\n  }\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message'': stringToSearch,\n    },\n    true\n  )\n  context.grafana.locationService.partial(\n    {\n      ''var-search_message_aux'': input,\n    },\n    true\n  )\n};\n\nfunction setActionsVisibility() {\n  const actions = document.getElementById(''actions'');\n  console.log(\"setActions\");\n  if (actions != null) {\n    const stored = localStorage.getItem(''showActions'');\n    console.log(stored);\n    if (stored == ''true'') {\n      actions.classList.toggle(''hidden'', true);\n      localStorage.setItem(''showActions'', ''true'');\n    }\n    else {\n      actions.classList.toggle(''hidden'', false);\n      localStorage.setItem(''showActions'', ''false'');\n    }\n  }\n}\nsetActionsVisibility();\n\n// Toggle on click\nfunction toggleActions() {\n  const stored = localStorage.getItem(''showActions'');\n  // console.log(stored);\n  stored == ''true'' ? localStorage.setItem(''showActions'', ''false'') : localStorage.setItem(''showActions'', ''true'');\n  setActionsVisibility();\n}\n\n\ndocument.getElementById(''toggleActions'').addEventListener(''click'', function (event) {\n  event.preventDefault();\n  toggleActions();\n});\n\n\ndocument.getElementById(''searchMsgInput'').addEventListener(''keydown'', function (event) {\n  if (event.key === ''Enter'') {\n    event.preventDefault();\n    searchMsg();\n  }\n});\n\nif (context.panelData.series.length \u003c 1) {\n  msgWarnLogs.innerText = \"No data in response.\";\n  msgWarnLogs.style.color = \"red\";\n}\nelse {\n  const logsRetrieved = context.panelData.series[0].length;\n  msgWarnLogs = document.getElementById(\"msgWarnLogs\");\n  if (logsRetrieved == 10000) {\n    msgWarnLogs.innerText = \"Only 10.000 logs are displayed, limit reached!\";\n    msgWarnLogs.style.color = \"red\";\n  }\n  else {\n    msgWarnLogs.innerText = `Logs retrieved: ${logsRetrieved}`;\n    msgWarnLogs.style.color = \"white\";\n  }\n}","content":"\u003cdiv class=\"containerMain\"\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n    {{#each data}}  \n    \u003ctr class=\"tableEntry\"\u003e\n      \u003ctd class=\"ts\"\u003e{{changeTime timestamp}}\u003c/td\u003e\n      \u003ctd class=\"ss\"\u003e{{subsystem}}\u003c/td\u003e\n      \u003ctd class=\"msg\"\u003e{{msg}}\u003c/td\u003e\n    \u003c/tr\u003e\n    {{/each}}\n\n  \u003c/table\u003e\n  \u003c/div\u003e\n  \u003cdiv class=\"toggleActions\" id=\"toggleActions\"\u003e\n    \u003ci class=\"fa fa-search\"\u003e\u003c/i\u003e\n  \u003c/div\u003e\n\n \u003cdiv class=\"actions hidden\" id=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n      \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n      \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n      \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n      \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","contentPartials":[],"defaultContent":"\u003cdiv class=\"containerMain\"\u003e\n  \u003cdiv class=\"tableContainer\"\u003e   \n    \u003cdiv id=\"msgWarnLogsContainer\"\u003e\n    \u003cp id=\"msgWarnLogs\"\u003e10000 logs returned\u003c/p\u003e\n    \u003c/div\u003e\n    \u003ctable class=\"dataTable\"\u003e\n    \u003ctr\u003e\n      \u003cth\u003eTimestamp\u003c/th\u003e\n      \u003cth\u003eSubsystem\u003c/th\u003e\n      \u003cth\u003eMessage\u003c/th\u003e\n    \u003c/tr\u003e\n  \u003c/table\u003e\n    NO DATA\n  \u003c/div\u003e\n  \u003cdiv class=\"toggleActions\" id=\"toggleActions\"\u003e\n    \u003ci class=\"fa fa-search\"\u003e\u003c/i\u003e\n  \u003c/div\u003e\n\n \u003cdiv class=\"actions hidden\" id=\"actions\"\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eLogs retrieval - select systems\u003c/div\u003e\n    \u003cdiv id=\"systemSelector\"\u003e\u003c/div\u003e\n    \u003cdiv class=\"sectionLabel\"\u003eSearch Msg:\u003c/div\u003e\n    \u003cinput id=\"searchMsgInput\" type=\"text\"/\u003e\n    \u003cdiv class=\"infoContainer\"\u003e\n      \u003cp\u003eRemember to escape with a \"\\\" any of the following characters:\u003c/p\u003e\n      \u003cp\u003e + - \u0026\u0026 || ! ( ) { } [ ] ^ \" ~ * ? : \\\n      \u003cp\u003eThis searching supports AND, OR and NOT operators\u003c/p\u003e\n      \u003cp\u003eE.G.: ( word1 AND word2 ) OR word3\u003c/p\u003e\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e","editor":{"format":"auto","language":"handlebars"},"editors":["helpers","afterRender","styles","default"],"externalStyles":[],"helpers":"const formatOptions = {\n  year: ''numeric'',\n  month: ''numeric'',\n  day: ''numeric'',\n  hour: ''2-digit'',\n  minute: ''2-digit'',\n  second: ''2-digit'',\n  fractionalSecondDigits: 3,\n  hourCycle: ''h23'',\n  timeZone: context.panelData.request.timezone != ''browser'' ? context.panelData.request.timezone : Intl.DateTimeFormat().resolvedOptions().timeZone\n};\n\ncontext.handlebars.registerHelper(''changeTime'', function (timestamp) {\n  const date = new Date(timestamp);\n  const formattedTime = date.toLocaleString(''en-US'', formatOptions);\n  const [datePart, timePart] = formattedTime.split('', '');\n  const [month, day, year] = datePart.split(''/'');\n  const [hours, minutes, seconds] = timePart.split('':'');\n  const [second, fraction] = seconds.split(''.'');\n  return `${day}/${month}/${year} ${hours}:${minutes}:${second}.${fraction}`;\n});","renderMode":"allRows","styles":".dt-row {\n  height: 100%;\n}\n\n.containerMain {\n  height: 100%;\n  width: 100%;\n  display: flex;\n  gap:1%;\n  padding: 0.5%;\n}\n.actions {\n  background-color: ${theme.colors.background.secondary};\n  padding: 2vh;\n  width: 30%;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n.sectionLabel {\n  color: ${theme.colors.text.primary};\n  font-family: ''Franklin Gothic Medium'', ''Arial Narrow'', Arial, sans-serif;\n  font-weight: 600;\n  border-bottom: 1px solid ${theme.colors.text.primary};\n  margin: 0.1vh;\n  width: 100%;\n}\n#systemSelector {\n  width: 100%;\n  height: 40%;\n  background-color: ${theme.colors.background.primary};\n  padding: 1vh;\n  overflow-y:scroll;\n  margin-bottom: 1vh;\n}\n#searchMsgInput {\n  width: 100%;\n  margin-bottom: 1vh;\n  background-color: ${theme.colors.background.primary};\n}\n.logsSystemContainer{\n  display: flex;\n  align-items: center;\n}\n.logsSystemLabel {\n  margin-left: 1vh;\n  text-transform: uppercase;\n}\n.infoContainer {\n  width: 100%;\n}\np {\n  margin: 0;\n}\n\n.toggleActionsContainer{\n  background-color: ${theme.colors.background.secondary};\n  padding: 1vh;\n  height: 100%;\n  display: flex;\n  align-items: center;\n}\n.toggleActions{\n  min-width: 3vh;\n  height: 100%;\n  // border-radius: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: ${theme.colors.background.secondary};\n\n}\n.toggleActions:hover{\n  min-width: 3vh;\n  width: 3vh;\n  height: 100%;\n  // border-radius: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor:pointer;\n  background-color: ${theme.colors.action.selectedBorder};\n}\n\n.hidden{\n  display: none;\n  width: 0px;\n}\n\n.tableContainer {\n  // background-color: blue;\n  width: 100%;\n  height: 100%;\n  overflow-y: scroll;\n  background-color: ${theme.colors.background.primary}\n}\n\n.dataTable {\n  position: relative;\n  width: 100%;\n  padding: 1vh;\n}\n\n.tableEntry {\n  max-height: 2%;\n}\n.ts {\n  max-width: 6vw;\n  min-width: 6vw;\n  width: 6vw%;\n}\n.ss {\n  max-width: 4vw;\n  min-width: 4vw;\n  width: 10%;\n}\n.msg {\n  max-width: 20vw;\n}\n\nth {\n  height: 1vh;\n  top: -1px;\n  margin: 0%;\n  position: -webkit-sticky;\n  position: sticky;\n  z-index: 2;\n}\n\n#msgWarnLogs {\n  margin: 0;\n}\n\n#msgWarnLogsContainer {\n  // background-color: red;\n  z-index: 6;\n  // position: fixed;\n\n}\n","wrap":true},"pluginVersion":"5.7.0","targets":[{"alias":"","bucketAggs":[],"datasource":{"type":"elasticsearch","uid":"F1zgMdwVz"},"metrics":[{"id":"1","settings":{"size":"10000"},"type":"raw_data"}],"query":"(${logs_subsystem:text}) AND (${search_message:text})","refId":"A","timeField":"@timestamp"}],"title":"","transformations":[{"id":"organize","options":{"excludeByName":{},"includeByName":{},"indexByName":{},"renameByName":{"@times